<?php
declare(strict_types=1);
$root=dirname(__DIR__);require_once $root.'/config/config.php';require_once $root.'/includes/services/WeaponRepairService.php';
$pdo=db();$playerId=(int)$pdo->query("SELECT id FROM players WHERE username='demo' LIMIT 1")->fetchColumn();$weapon=$pdo->query("SELECT pw.id,pw.durability,wt.max_durability FROM player_weapons pw JOIN weapon_types wt ON wt.id=pw.weapon_type_id WHERE pw.player_id={$playerId} LIMIT 1")->fetch(PDO::FETCH_ASSOC);if($playerId<1||!$weapon){fwrite(STDERR,"seed_weapon_missing\n");exit(2);}
$weaponId=(int)$weapon['id'];$originalDurability=(int)$weapon['durability'];$originalResourceStmt=$pdo->prepare('SELECT naquadah FROM player_resources WHERE player_id=?');$originalResourceStmt->execute([$playerId]);$originalNaquadah=(int)$originalResourceStmt->fetchColumn();$damaged=max(0,(int)$weapon['max_durability']-1);$pdo->prepare('UPDATE player_weapons SET durability=? WHERE id=? AND player_id=?')->execute([$damaged,$weaponId,$playerId]);$pdo->prepare("DELETE FROM player_cooldowns WHERE player_id=? AND cooldown_key='weapon_repair'")->execute([$playerId]);
$service=new WeaponRepairService($pdo);$result=$service->repair($playerId,$weaponId);$checks=['cost_formula'=>(int)$result['repair_cost']===(int)$result['missing_durability']*(int)$result['tier']*10,'queue_id'=>(int)($result['construction_queue_id']??0)>0,'restored_durability'=>(int)$result['durability']===(int)$weapon['max_durability']];$q=$pdo->prepare("SELECT queue_type,item_key,status FROM construction_queue WHERE id=? AND player_id=?");$q->execute([(int)$result['construction_queue_id'],$playerId]);$queue=$q->fetch(PDO::FETCH_ASSOC);$checks['queue_persisted']=is_array($queue)&&$queue['queue_type']==='weapon_repair'&&$queue['status']==='completed';$originalResourceStmt->execute([$playerId]);$after=(int)$originalResourceStmt->fetchColumn();$checks['resource_deducted']=$after===$originalNaquadah-(int)$result['repair_cost'];$event=$pdo->prepare("SELECT payload FROM game_events WHERE player_id=? AND event_type='weapon_repaired' AND entity_id=? ORDER BY id DESC LIMIT 1");$event->execute([$playerId,$weaponId]);$payload=json_decode((string)$event->fetchColumn(),true);$checks['audit_metadata']=is_array($payload)&&isset($payload['construction_queue_id'],$payload['missing_durability'],$payload['cost']);
$pdo->prepare('UPDATE player_weapons SET durability=? WHERE id=? AND player_id=?')->execute([$originalDurability,$weaponId,$playerId]);$pdo->prepare('UPDATE player_resources SET naquadah=? WHERE player_id=?')->execute([$originalNaquadah,$playerId]);$pdo->prepare('DELETE FROM construction_queue WHERE id=? AND player_id=?')->execute([(int)$result['construction_queue_id'],$playerId]);$pdo->prepare("DELETE FROM game_events WHERE player_id=? AND event_type='weapon_repaired' AND entity_id=? AND created_at>=DATE_SUB(NOW(),INTERVAL 2 MINUTE)")->execute([$playerId,$weaponId]);$failures=array_keys(array_filter($checks,static fn(bool $ok):bool=>!$ok));echo json_encode(['status'=>$failures?'failed':'passed','result'=>$result,'queue'=>$queue,'checks'=>$checks,'failures'=>$failures],JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR).PHP_EOL;exit($failures?1:0);
